/* AIOPEDIA — catalog: companies (the organizations building AI) */
window.AIOPEDIA = window.AIOPEDIA || {};
window.AIOPEDIA.companies = [
  { id: "openai", name: "OpenAI", category: "companies", year: 2015, tagline: "The lab that put generative AI in everyone's hands.", summary: "Founded 2015 as a nonprofit, now the world's most influential AI company — creator of GPT, ChatGPT, DALL·E, Whisper, Sora and the o-series reasoning models.", body: [
    "OpenAI was founded in December 2015 as a nonprofit research lab by Sam Altman, Elon Musk, Ilya Sutskever and others, with a charter to ensure artificial general intelligence benefits all of humanity. It pivoted to a 'capped-profit' structure in 2019 to attract capital while maintaining a mission-bound governance board, and the GPT line — GPT-2 (2019), GPT-3 (2020), and especially ChatGPT (2022) — made it the defining force of the generative-AI era. A landmark partnership with Microsoft brought billions in compute in exchange for exclusive cloud and commercialization rights.",
    "OpenAI's trajectory has been as turbulent as it was triumphant: the board's brief firing and reinstatement of Sam Altman in November 2023, the 2024 departures of co-founder Ilya Sutskever and CTO Mira Murati, and an ongoing corporate restructuring toward for-profit governance. It remains the benchmark setter for frontier models and the center of gravity for the AI economy — and for the debate about whether its 'benefit all humanity' charter can survive its scale."
  ], tags: ["frontier lab", "us", "chatgpt"], related: ["chatgpt", "gpt", "sam-altman", "ilya-sutskever"], sources: ["OpenAI, 2015 — Founding charter"], status: "core" },
  { id: "anthropic", name: "Anthropic", category: "companies", year: 2021, tagline: "The AI safety company that built Claude.", summary: "Founded 2021 by ex-OpenAI researchers, a public-benefit corporation whose frontier models (Claude) are built around constitutional AI and a safety-first ethos.", body: [
    "Anthropic was founded in 2021 by Dario and Daniela Amodei and several former OpenAI researchers who left over disagreements about the pace and governance of frontier AI. From the start it has organized itself around safety: a public-benefit corporation, a Long-Term Benefit Trust for oversight, a 'Responsible Scaling Policy' that gates model deployment on risk thresholds, and a research program on interpretability that publishes mechanistic analyses of model internals.",
    "Its Claude family — from Claude 1 (2023) to Claude 4 (2025) — became known for nuanced alignment, long-context competence and strong coding, and its constitutional-AI approach substitutes model-generated critique for large-scale human rating. Anthropic is the leading voice in frontier-safety policy, an early advocate for compute thresholds in regulation, and its partnership with Amazon positioned it as the enterprise-safe alternative to OpenAI. It is the clearest working example of a lab that treats safety as the product."
  ], tags: ["frontier lab", "us", "safety"], related: ["claude", "alignment", "constitutional-ai"], sources: ["Anthropic, 2021 — Public benefit corporation charter"], status: "core" },
  { id: "google-deepmind", name: "Google DeepMind", category: "companies", year: 2010, tagline: "The lab behind AlphaGo, AlphaFold and Gemini.", summary: "Founded 2010 in London, acquired by Google in 2014, merged with Google Brain in 2023 — a research powerhouse with a Nobel Prize and frontier multimodal models.", body: [
    "DeepMind was founded in 2010 by Demis Hassabis, Shane Legg and Mustafa Suleyman with the explicit goal of solving intelligence, and acquired by Google in 2014. Its research-first culture produced a string of landmark systems: AlphaGo (2016), AlphaZero (2017), AlphaFold (2020, which won the 2024 Nobel Prize in Chemistry), AlphaStar for StarCraft, and MuZero's self-play generality. The 2023 merger with Google Brain created Google DeepMind, which now develops Gemini, the model family integrated across Google's consumer empire.",
    "DeepMind's significance is depth over hype: it is the lab most responsible for AI's scientific legitimacy, publishing at the top of biology, chemistry and mathematics while quietly powering products from AlphaFold databases to Gemini. Its dual identity — research institute inside a trillion-dollar ad company — is a running tension, and figures like Hassabis have become leading voices in the global safety debate, arguing for careful frontier governance while racing to build AGI."
  ], tags: ["frontier lab", "uk", "research"], related: ["alphago", "alphafold", "gemini", "demis-hassabis"], sources: ["DeepMind, 2010 — Founding; Google acquisition 2014"], status: "core" },
  { id: "google", name: "Google (AI)", category: "companies", year: 2015, tagline: "The search giant that invented the transformer — and now lives inside Gemini.", summary: "Google Brain (2011), the transformer (2017), BERT, TPUs, AI Overviews, Android Gemini and the largest AI distribution network on Earth.", body: [
    "Google has been an AI leader longer than most people realize: the deep-learning research of Google Brain (2011), the transformer architecture invented inside Google in 2017 — the technology behind every modern LLM — BERT (2018), and the custom TPU chips that made large-scale training economical. After merging Brain with DeepMind in 2023, Google's AI strategy consolidated around Gemini, which now touches Search (AI Overviews), Android, Workspace, Chrome, the Pixel line and the standalone Gemini app and API.",
    "Google's AI position is distinctive for its scale of distribution and infrastructure rather than frontier-model bragging rights: it has the deepest talent bench, the largest cloud and TPU fleet, and the most users. It also faces the hardest contradictions — an ad business that depends on clicks colliding with an assistant that answers without clicks, and antitrust rulings that constrain how it can bundle AI. The transformer paper may be the most consequential intellectual property in the field, and Google owns it."
  ], tags: ["big tech", "us", "infrastructure"], related: ["transformer", "gemini", "bert", "google-deepmind"], sources: ["Vaswani et al., 2017; Google, 2018 — BERT release"], status: "core" },
  { id: "meta-ai", name: "Meta AI", category: "companies", year: 2013, tagline: "The lab that made frontier models open.", summary: "FAIR (2013) + GenAI teams: Llama, PyTorch, Segment Anything, Movie Gen — Meta's open-weights strategy reshaped the industry.", body: [
    "Meta's AI efforts began with FAIR (Facebook AI Research, 2013), a fundamental-research lab led by Yann LeCun that produced PyTorch (2016) — now the standard deep-learning framework — and major vision models. The generative era brought the company's signature move: releasing the Llama family with open weights, from Llama 1 (2023) to Llama 4 (2025), transforming Meta into the godfather of the open-weights ecosystem and making local AI viable for the entire world.",
    "Meta AI's strategy is unapologetically open-source-forward — it trades direct model revenue for ecosystem influence, cheaper infrastructure via Meta's own deployment at planetary scale (WhatsApp, Instagram, Facebook, Ray-Ban glasses), and goodwill. The same compute that serves billions of users lets it train frontier-class models without selling API access. Meta's AI also powers Llama-based assistants across its apps and a research portfolio spanning computer vision (SAM), speech, and self-supervised learning — the LeCun vision of models that learn like children rather than through language alone."
  ], tags: ["big tech", "us", "open weights"], related: ["llama", "pytorch", "yann-lecun", "hugging-face"], sources: ["Meta AI, 2013 — FAIR founding; 2023 — Llama release"], status: "core" },
  { id: "microsoft-ai", name: "Microsoft AI", category: "companies", year: 2019, tagline: "The AI company with $13B in OpenAI compute and a billion-seat distribution deal.", summary: "OpenAI's largest backer and the force behind GitHub Copilot, Copilot+ PCs, Phi and Azure AI — AI as the new Windows.", body: [
    "Microsoft's AI bet is the largest and most financially committed of any company: a $13 billion partnership with OpenAI that made Azure the exclusive cloud for OpenAI models, and in return gave Microsoft first claim on the most consequential technology of the decade. The output has been total product integration — GitHub Copilot, Microsoft 365 Copilot, Windows Copilot, Bing — alongside its own research line (the small-but-mighty Phi models) and the enterprise AI stack of Azure OpenAI Service.",
    "Microsoft's wager is that AI becomes the operating layer of software the way Windows was the operating system of the PC: every enterprise workflow, re-founded on models, with Microsoft collecting the platform tax. CEO Satya Nadella's 'platform shift' framing has driven one of the largest stock-market gains in history. The risks are equally structural: dependence on OpenAI (whose for-profit restructuring and model deals it must navigate), antitrust scrutiny, and the question of whether Copilot subscriptions will ever justify their cost."
  ], tags: ["big tech", "us", "enterprise"], related: ["phi", "copilot", "openai", "github-copilot", "satya-nadella"], sources: ["Microsoft, 2019–2023 — OpenAI partnership"], status: "core" },
  { id: "nvidia", name: "NVIDIA", category: "companies", year: 1993, tagline: "The company selling shovels in the AI gold rush.", summary: "From gaming GPUs to the near-monopoly on AI training hardware — CUDA, Hopper, Blackwell, and a market valuation that made it the world's most valuable company.", body: [
    "NVIDIA was founded in 1993 to make graphics processors, and the accidental discovery that GPUs are also astonishingly good at matrix math made it the indispensable hardware layer of AI. The CUDA platform (2006) let researchers program GPUs for general computation; AlexNet's 2012 win proved the point; and every deep-learning revolution since has run on NVIDIA silicon. Its modern AI line spans A100/H100 training chips, the GH200 and GB200 'superchips', DGX systems, and the InfiniBand networking that stitches data centers together.",
    "NVIDIA's dominance is historical in scale: it controls an estimated 80–95% of the AI accelerator market, and at points in 2024–2025 its market capitalization made it the world's most valuable public company. That position creates both strategic leverage — every frontier lab, cloud and sovereign AI program is a customer — and geopolitical gravity, as export controls on its most advanced chips became a central instrument of US-China technology policy. Jensen Huang's prediction that 'the world is going to be an AI factory' is fast becoming a description of the present."
  ], tags: ["hardware", "us", "infrastructure"], related: ["gpu", "inference", "training", "hardware-ai", "jensen-huang"], sources: ["NVIDIA, 2006 — CUDA launch"], status: "core" },
  { id: "hugging-face", name: "Hugging Face", category: "companies", year: 2016, tagline: "The GitHub of AI.", summary: "The platform where open models, datasets, and the community live — Transformers library, Model Hub, Spaces — the default home of open AI.", body: [
    "Hugging Face began in 2016 as a chatbot startup and became something more important: the central repository of open AI. Its Transformers library (2018) made state-of-the-art models a pip-install away, and the Hub grew into the canonical registry for open models, datasets, papers and demos — with millions of models, from Llama and Qwen to community fine-tunes, alongside Spaces, where anyone can host an AI app in seconds.",
    "The company's role is infrastructural and cultural: it is where open-weights research actually gets distributed, benchmarked and built upon, and its leadership (CEO Clem Delangue) is an outspoken advocate for 'open-source AI'. Its business is the platform — enterprise accounts, AI inference endpoints, datasets and the ongoing work of standards. If open AI has a home on the internet, it is huggingface.co, and its rise tracks the open-weights movement's own."
  ], tags: ["platform", "open source", "community"], related: ["pytorch", "llama", "fine-tuning", "transformers-library"], sources: ["Hugging Face, 2016 — founding"], status: "core" },
  { id: "mistral-ai", name: "Mistral AI", category: "companies", year: 2023, tagline: "Europe's AI champion — efficient, open, sovereign.", summary: "Paris-founded lab (2023) whose Apache-licensed models (7B, Mixtral, Large) proved efficiency can rival scale and gave Europe its own frontier voice.", body: [
    "Mistral AI was founded in Paris in 2023 by Arthur Mensch, Timothée Lacroix and Guillaume Lample, all formerly of DeepMind and Meta, with €105M seed funding — Europe's largest AI seed round. Its strategy is efficiency and openness: small models that punch above their weight, the Mixtral mixture-of-experts line, and an Apache 2.0 licensing stance that keeps the community on its side. Its flagship Mistral Large and the Le Chat assistant pushed the lab into consumer and enterprise territory.",
    "Mistral's significance is geopolitical as much as technical: it is the standard-bearer for European AI sovereignty, an answer to the US-China duopoly, and a proof point that frontier capability can come from lean, open-weights labs rather than trillion-dollar balance sheets. Its commercial model — open releases plus a hosted API — became the template for 'open core' AI, and its success helped seed a wave of European foundation-model investment."
  ], tags: ["frontier lab", "europe", "open weights"], related: ["mistral", "mixture-of-experts", "llama"], sources: ["Mistral AI, 2023 — founding"], status: "core" },
  { id: "xai", name: "xAI", category: "companies", year: 2023, tagline: "The 'truth-seeking' challenger with the biggest cluster on Earth.", summary: "Elon Musk's 2023 lab: Grok, Colossus (100k+ GPU supercluster), real-time X data, and a merger that fused data, compute and distribution.", body: [
    "xAI was founded by Elon Musk in March 2023 with an unusual pitch: an AI lab built to understand the universe, monetized fast, and deliberately less constrained than rivals. Grok launched in November 2023 with real-time access to X data and an irreverent brand, and Grok 3 (2025) reached the top of frontier benchmarks. The lab's Colossus data center — reportedly over 100,000 GPUs stood up in under four months — became a symbol of American AI velocity.",
    "xAI's 2025 merger with X (and its $33B valuation round) created a rare vertical integration: the model, the real-time data stream, the distribution platform and the compute in one company. The strategy is controversial — X's data carries content-moderation baggage, and 'maximally truth-seeking' has meant fewer guardrails than rivals — but it established real-time data as a competitive moat and made xAI a top-tier player within two years of founding."
  ], tags: ["frontier lab", "us", "real-time"], related: ["grok", "twitter-x", "large-language-model"], sources: ["xAI, 2023 — founding announcement"], status: "core" },
  { id: "stability-ai", name: "Stability AI", category: "companies", year: 2020, tagline: "The company that open-sourced image generation.", summary: "Founded 2020, released Stable Diffusion (2022) with open weights, igniting local generative AI and the open/closed model wars.", body: [
    "Stability AI, founded by Emad Mostaque in 2020, became famous for one decision: releasing Stable Diffusion in August 2022 with open weights, making state-of-the-art text-to-image generation available to anyone with a consumer GPU. The release detonated an ecosystem — AUTOMATIC1111, ComfyUI, LoRA fine-tunes, and a flood of community tools — and made 'open model' a competitive weapon that forced the closed labs to respond.",
    "The company's trajectory since has been a cautionary tale about open-source AI economics: leadership turbulence (Mostaque's departure in 2024), an unstable business model selling enterprise APIs against free weights, and legal exposure from the copyright lawsuits aimed at image generators. Its legacy, however, is secure: Stable Diffusion proved that frontier capability can be a public good, and the ecosystem it spawned — including most local image generation today — is the direct product of that choice."
  ], tags: ["startup", "uk", "open weights"], related: ["stable-diffusion", "midjourney-inc", "dall-e"], sources: ["Stability AI, 2022 — Stable Diffusion release"], status: "emerging" },
  { id: "midjourney-inc", name: "Midjourney (the company)", category: "companies", year: 2021, tagline: "The profitable, un-funded outlier of AI art.", summary: "Independent lab led by David Holz; built Midjourney into a beloved creative tool without venture money and with an almost silent public posture.", body: [
    "Midjourney, Inc., founded by David Holz (co-founder of Leap Motion) in 2021, is one of AI's strangest successes: a profitable company built on a subscription art tool, no major venture funding, and an almost monastic public posture — no press tours, no model papers, no benchmarks theater. The product's distinctive aesthetic made it the default tool for concept artists, designers and game studios, and its community, born in Discord, is among the most engaged in AI.",
    "The company's philosophy — that AI art should be a medium, not a demo, and that quality and taste beat scale — produced a durable product while rivals burned billions. Midjourney also sits at the sharp end of the copyright fight: its training data, like Stable Diffusion's, was scraped without consent, and it is a defendant in the class-action lawsuits that will define whether generative models owe artists anything. The company answers, as it does everything, mostly with silence."
  ], tags: ["startup", "us", "creative"], related: ["midjourney", "stable-diffusion", "generative-ai"], sources: ["—"], status: "core" },
  { id: "cohere", name: "Cohere", category: "companies", year: 2019, tagline: "Enterprise AI from the Transformer paper's co-author.", summary: "Founded 2019 by Aidan Gomez (co-author of 'Attention Is All You Need'), Cohere focuses on private, enterprise-grade language AI.", body: [
    "Cohere was founded in 2019 by Aidan Gomez, Nick Frosst and Ivan Zhang with a thesis that the enterprise — not consumers — would be the durable market for language AI. The company built enterprise platforms for RAG, search, classification and command models with a strict emphasis on data privacy: models deployable in the customer's own cloud or on-premise, a posture that won banks, insurers and governments as clients in Canada, Europe and beyond.",
    "Cohere's significance is the 'sovereign AI' enterprise market: while OpenAI and Anthropic raced for consumer mindshare, Cohere quietly built the reference stack for organizations that cannot send their data to a US cloud. Its Command and Embed models, and later multilingual models (including strong non-English performance), made it the default choice for regulated industries, and its $500M+ funding and Canadian anchor gave the country its flagship AI company. The bet — that trust, privacy and control beat raw capability in the enterprise — has aged well."
  ], tags: ["enterprise", "canada", "privacy"], related: ["retrieval-augmented-generation", "embeddings", "transformer"], sources: ["Cohere, 2019 — founding"], status: "core" },
  { id: "perplexity-ai", name: "Perplexity AI", category: "companies", year: 2022, tagline: "The answer engine that took on Google Search.", summary: "Founded 2022 by Aravind Srinivas; Perplexity's cited, real-time answers grew to a leading 'answer engine' and a new pattern for search.", body: [
    "Perplexity AI, founded by ex-OpenAI researcher Aravind Srinivas, launched in 2022 with a deceptively simple product: a search engine that answers questions in prose, with sources, in real time. By combining live web retrieval with frontier models, Perplexity produced answers that were current and citable — the thing plain chatbots could not do — and its growth (from zero to tens of millions of queries, and a $9B+ valuation by 2025) made it the most credible challenger to Google's core product in a generation.",
    "Perplexity's rise launched the 'answer engine' category and forced Google to ship AI Overviews and OpenAI to ship SearchGPT in response. It also raised the search industry's hardest questions — publisher compensation (news outlets accused it of content laundering), the reliability of cited answers, and whether answer engines destroy the web's traffic economy. Whatever its long-term fate, Perplexity proved that a small team with a good product could stand between the world's questions and the world's most powerful company."
  ], tags: ["startup", "us", "search"], related: ["retrieval-augmented-generation", "agents", "chatgpt"], sources: ["Perplexity AI, 2022 — founding"], status: "core" },
  { id: "alibaba-cloud", name: "Alibaba Cloud (Qwen)", category: "companies", year: 2009, tagline: "China's open-weights powerhouse.", summary: "Alibaba Cloud's Qwen family — open weights at every size, dominant in open benchmarks, and the default small model of local AI worldwide.", body: [
    "Alibaba Cloud, the cloud arm of Alibaba Group founded in 2009, launched the Qwen model family in 2023 and has since run one of the most prolific open-model programs in the world: Qwen2, Qwen2.5 and Qwen3 across dense and MoE architectures, from 0.5B to 235B+ parameters, with specialized models for code, math, vision, audio and embedding. The family consistently leads open-model leaderboards, and its open-weights licensing made it the foundation of countless products across Asia and beyond.",
    "Qwen's strategic significance mirrors Meta's: Alibaba gives away frontier-class weights to anchor an ecosystem, steer standards, and drive adoption of its cloud and enterprise stack. The program also positions China squarely inside the open-weights movement, complicating Western assumptions about Chinese AI being closed by default. For the practical world, Qwen models — especially the 3–14B tier — have become the most recommended first models for local AI because of their small footprint, strong multilingual performance and permissive licensing."
  ], tags: ["big tech", "china", "open weights"], related: ["qwen", "llama", "deepseek"], sources: ["Alibaba Cloud, 2023 — Qwen launch"], status: "core" },
  { id: "baidu", name: "Baidu", category: "companies", year: 2000, tagline: "China's original AI-first search giant.", summary: "Founded 2000 by Robin Li; deep-learning pioneer (ERINE), autonomous driving (Apollo), and one of the earliest big-tech AI investments.", body: [
    "Baidu, China's dominant search engine founded by Robin Li in 2000, was among the first big tech companies to bet everything on AI: it opened a deep-learning research institute in 2013, trained its own large model (ERINE, launched 2019, before ChatGPT), and built Apollo, one of the world's most extensive autonomous-driving platforms, plus a full self-driving ride-hailing service in multiple Chinese cities.",
    "Baidu's path is a lens on Chinese AI more broadly: enormous investment, close integration of search and AI, and intense competition — ERINE now competes with Qwen, DeepSeek and ByteDance's Doubao, and Baidu's public valuation reflects how much of the Chinese AI prize has been captured by younger entrants. Its Apollo robotaxi network, however, remains the most concrete large-scale autonomous-vehicle deployment outside the US, and its cloud AI business anchors the enterprise market."
  ], tags: ["big tech", "china", "autonomous"], related: ["autonomous-vehicles", "alibaba-cloud", "deepseek"], sources: ["Baidu, 2013 — Institute of Deep Learning; 2019 — ERINE"], status: "core" },
  { id: "ibm", name: "IBM", category: "companies", year: 1911, tagline: "The century-old giant that has been an AI player in every era.", summary: "From Deep Blue to Watson to Granite: IBM has shipped AI in every wave — the company that beat a world champion at chess and put AI in the enterprise.", body: [
    "IBM has the longest continuous involvement with AI of any company. Its researchers defined much of the early field — Arthur Samuel built machine learning's first programs there, and the IBM 704 ran the perceptron — and in 1997 Deep Blue beat Garry Kasparov at chess, AI's first global media event. Watson's 2011 Jeopardy! win positioned IBM as the enterprise AI vendor, though the subsequent push to sell Watson into medicine became a cautionary tale about overpromising.",
    "IBM's current AI bet is more sober: the watsonx platform, the open-source Granite model family (trained on permissively licensed data to avoid copyright suits), and a focus on regulated industries. The company that coined 'artificial intelligence' in public discourse, repeatedly failed to monetize it, and kept coming back is the industry's persistence test — and its Granite models, released under Apache licensing, are now a quiet pillar of the open-weights ecosystem."
  ], tags: ["legacy", "enterprise", "watson"], related: ["deep-blue", "expert-systems", "watson"], sources: ["IBM, 1997 — Deep Blue vs Kasparov; IBM, 2023 — watsonx and Granite"], status: "core" },
  { id: "amazon-ai", name: "Amazon (AI)", category: "companies", year: 1994, tagline: "The retail and cloud giant that sells AI as infrastructure.", summary: "AWS — the world's largest AI infrastructure provider, home of Bedrock, SageMaker and Trainium chips — and the company that put recommendation systems at global scale.", body: [
    "Amazon's AI significance is infrastructure: AWS hosts more AI training and inference than any rival, and its Bedrock service resells frontier models (Claude, Llama, Mistral) as APIs, making Amazon the neutral 'AI department store' of the enterprise. Its custom Trainium and Inferentia chips undercut Nvidia's pricing, and SageMaker is the default training platform for much of industry. Amazon's own models (Nova, released 2024) round out a strategy of being the layer everyone else builds on.",
    "Amazon's first AI triumph was quieter: its recommendation engine, built in the late 1990s and refined with machine learning, proved that collaborative filtering could drive real commerce and seeded the entire recommendation-systems field. The company's Alexa assistant (2014) was the mass-market voice AI before the LLM era, and Anthropic's $8B investment and cloud partnership made Amazon both funder and host of one of the frontier's two leading labs."
  ], tags: ["aws", "infrastructure", "recommendations"], related: ["anthropic", "recommendation-systems", "nvidia", "amazon"], sources: ["AWS, 2023 — Bedrock launch; Amazon, 2014 — Alexa; Linden, Smith & York, 2003 — Amazon.com recommendations"], status: "core" },
  { id: "apple-ai", name: "Apple (AI)", category: "companies", year: 1976, tagline: "The privacy-first AI company — intelligence where your data stays.", summary: "Apple's on-device AI strategy — from Siri to Apple Intelligence — built on the argument that the most personal AI is the one that runs locally and privately.", body: [
    "Apple approaches AI like no other frontier player: its bets are on-device and privacy-first. Siri (2011) was the first mass-market voice assistant, and its stagnation became the industry's standing example of a first-mover losing the AI race. Apple Intelligence (2024) — a blend of small on-device models (including Gemma and Llama-class networks), on-device rewriting and summarization, and private cloud compute for heavier tasks — is Apple's attempt to win the era it helped open.",
    "Apple's significance is structural: it owns the world's most valuable distribution channel (over 2 billion devices), its chip design (the Neural Engine in Apple silicon) gives it unique leverage in on-device inference, and its privacy posture — server-side processing that Apple cannot read, encrypted model routing — is the strongest counter-narrative to the data-hungry cloud labs. The company's bet is that the next AI battleground is not who trains the biggest model but who can run a good enough one privately on the device in your pocket."
  ], tags: ["apple", "on-device", "privacy"], related: ["siri", "apple-intelligence", "ai-safety"], sources: ["Apple, 2024 — Apple Intelligence announcement"], status: "core" },
  { id: "tesla-ai", name: "Tesla (AI)", category: "companies", year: 2003, tagline: "The car company that became an AI company.", summary: "Tesla's bet that vision-based neural nets and 'we are an AI robotics company' would deliver full self-driving and the Optimus robot — among the largest real-world AI deployments.", body: [
    "Tesla's AI strategy is a single radical bet: that full autonomy can be achieved with cameras and neural networks alone, without lidar, at massive fleet scale. Its FSD (Full Self-Driving) system runs a unified vision transformer trained on the data of millions of cars — 'the largest real-world AI training program' per the company — and its Dojo supercomputer and in-house inference chips push the vertical integration further than any rival. In 2024-25 Tesla repositioned as 'an AI robotics company', pivoting its future story toward the Optimus humanoid robot and a Robotaxi network.",
    "Tesla is the industry's most polarizing AI player: supporters see the only credible path to full autonomy and physical AI at scale; skeptics point to years of missed 'full self-driving' deadlines, regulator clashes and the technical debate about vision-only autonomy. Its influence is nonetheless enormous — every automaker now runs a version of the 'data flywheel' playbook Tesla pioneered, and the Optimus humanoid race it entered has become one of the defining competitions of the physical-AI era."
  ], tags: ["autonomous driving", "robotics", "vision"], related: ["autonomous-driving", "robotics", "elon-musk", "computer-vision"], sources: ["Tesla, 2016–2025 — Autopilot/FSD releases and AI Day presentations"], status: "core" },
  { id: "deepseek-company", name: "DeepSeek (company)", category: "companies", year: 2023, tagline: "The quant-fund spin-off that shocked the world's markets.", summary: "The Chinese AI lab, born from the hedge fund High-Flyer, whose ultra-cheap frontier models triggered a global reassessment of AI economics.", body: [
    "DeepSeek is the AI research arm of High-Flyer, one of China's largest quantitative hedge funds — a lineage that gave the lab something unusual in AI: enormous pre-existing GPU stockpiles, engineering discipline, and no external investors demanding monetization. Its DeepSeek-V3 (late 2024) matched frontier Western models while reportedly training for under $6 million of compute, and DeepSeek-R1 (January 2025) replicated o1-class reasoning with fully open weights. The announcement wiped roughly a trillion dollars from global market value in a day.",
    "DeepSeek's significance is geopolitical as much as technical: it demonstrated that US chip export controls could be answered with algorithmic efficiency, that open models could reach the frontier, and that the 'China can't compete' consensus was wrong. The company stays deliberately opaque — few public executives, no investor tours — while its papers set the field's agenda on efficient MoE training and reinforcement learning with verifiable rewards. DeepSeek forced every lab on Earth to answer one question: why does frontier AI have to cost this much?"
  ], tags: ["china", "efficiency", "open weights"], related: ["deepseek", "mixture-of-experts", "xai", "baidu"], sources: ["DeepSeek-AI, 2024–2025 — V3 & R1 technical reports"], status: "core" },
  { id: "coreweave", name: "CoreWeave", category: "companies", year: 2017, tagline: "The GPU cloud that became AI's infrastructure darling.", summary: "The cloud provider born as an Ethereum mining firm that pivoted to GPU compute — now the company that literally runs OpenAI's training.", body: [
    "CoreWeave began in 2017 mining Ethereum and ended up with a warehouse of GPUs that nobody else knew how to manage at scale; in 2020 it pivoted to cloud GPU rental, and by 2023 it was the fastest-growing AI infrastructure company on Earth. Its pitch — cheaper, more flexible, GPU-optimized infrastructure than the hyperscalers — won Microsoft (a multi-billion-dollar contract), OpenAI (a massive training deal making CoreWeave effectively the compute partner of the frontier), and every AI startup needing Nvidia hardware at scale.",
    "CoreWeave's rise is a lens on the AI economy: compute, not algorithms, is the scarce resource, and the companies that own access to it capture enormous value. Its 2025 IPO, built largely on a single customer (OpenAI), also exposed the fragility of that model — concentration risk, debt-fueled expansion, and dependence on Nvidia's roadmap. The 'GPU cloud' it pioneered has since been replicated by Lambda, Together AI and every hyperscaler, making compute the most contested commodity of the AI boom."
  ], tags: ["infrastructure", "gpu cloud", "compute"], related: ["nvidia", "openai", "cuda"], sources: ["CoreWeave, 2023–2025 — contracts, funding and IPO filings"], status: "core" },
  { id: "scale-ai", name: "Scale AI", category: "companies", year: 2016, tagline: "The data-labeling giant that became AI's quality gatekeeper.", summary: "Alexandr Wang's Scale AI — human-in-the-loop data annotation and frontier evals at industrial scale, now the company that grades the models.", body: [
    "Scale AI, founded by Alexandr Wang in 2016 while he was a MIT undergraduate, built the data-labeling workforce and software that trained the first generation of commercial AI — bounding boxes for autonomous driving, sentiment labels for NLP, and the reinforcement-learning-from-human-feedback pipelines that made ChatGPT behave. Its platform combines millions of human annotators with model-assisted tooling, letting frontier labs ship training data at a pace no internal team could match. By 2024 Scale had become a central vendor to nearly every major lab, including OpenAI and the US Department of Defense.",
    "Scale's second act is evaluation: as training data matured, the company pivoted toward frontier evals and model scoring — 'the referee of the AI race' — running the human expert panels that grade the hardest model capabilities. Its rise is a lens on the industry's unglamorous truth: the most valuable AI company of the 2020s may be the one that labels and grades the models, not the one that builds them. Scale also anchors the debate over AI labor conditions — the pay and treatment of its annotation workforce is a recurring ethics story."
  ], tags: ["data", "infrastructure", "evals"], related: ["openai", "nvidia", "fine-tuning", "computer-vision", "reinforcement-learning-from-human-feedback", "alexandr-wang"], sources: ["Scale AI, 2016 — founding; 2024 — public funding round"], status: "core" },
  { id: "cerebras", name: "Cerebras", category: "companies", year: 2016, tagline: "The wafer-scale chipmaker betting that bigger silicon wins.", summary: "Cerebras Systems — builder of the WSE, the largest chip ever made — an American alternative to NVIDIA for training and inference.", body: [
    "Cerebras Systems was founded in 2016 to solve the AI-hardware problem by going bigger instead of networking more: its Wafer-Scale Engine is a single silicon wafer turned into one chip, with hundreds of thousands of AI cores and on-die memory, eliminating the inter-chip bottlenecks that plague GPU clusters. The WSE-3 powers Cerebras's CS-3 systems, and its wafer-scale service has trained large models — including open-weight releases in the Llama class — with radically simplified cluster management.",
    "Cerebras matters geopolitically as well as technically: as the leading American challenger to NVIDIA's near-monopoly, it is a centerpiece of US efforts to keep frontier AI compute domestic, and its 2025 IPO was among the largest of the AI-infrastructure wave. Its trade-offs — a proprietary programming model and fewer ecosystem tools than CUDA — have kept it a niche player, but its bet that the future is fewer, bigger chips is increasingly shared by the industry."
  ], tags: ["hardware", "us", "wafer scale"], related: ["nvidia", "cuda", "compute", "coreweave"], sources: ["Cerebras, 2016 — founding; 2024 — WSE-3 announcement"], status: "core" },
  { id: "groq", name: "Groq", category: "companies", year: 2016, tagline: "The startup that made LLM inference feel instant.", summary: "Groq's LPU (Language Processing Unit) delivers token speeds that stunned the industry — a deterministic, software-defined architecture for pure inference speed.", body: [
    "Groq was founded in 2016 by former Google TPU engineers, including Jonathan Ross, who had worked on the original TPU team. Its Language Processing Unit (LPU) is a single-core, deterministic tensor-streaming architecture with no scheduling overhead, which translates into extraordinary inference latency — when Groq's public API demoed open models at hundreds to thousands of tokens per second in 2024, 'ridiculously fast' became the company's unofficial slogan and its service promptly melted under viral demand.",
    "Groq's significance is the inference-economics question: as AI shifts from training to serving, the cost and speed of running models matters as much as building them, and Groq showed that purpose-built inference hardware can beat GPUs on latency while being cheaper per token. Its $2.8B 2024 raise, partnerships with Meta and Mistral for frontier open models, and its role in the 'inference is the new oil' thesis make it the purest bet on AI's operating cost collapsing."
  ], tags: ["hardware", "inference", "us"], related: ["nvidia", "cuda", "compute", "vllm", "coreweave"], sources: ["Groq, 2016 — founding; 2024 — Meta and Mistral partnerships"], status: "core" },
  { id: "databricks", name: "Databricks", category: "companies", year: 2013, tagline: "The lakehouse company that turned open models into enterprise infrastructure.", summary: "Databricks — born from the creators of Apache Spark — built the data-and-AI platform of the enterprise, and DBRX, an open-weights MoE model, as a statement.", body: [
    "Databricks was founded in 2013 by the creators of Apache Spark — Ali Ghodsi, Matei Zaharia and colleagues from UC Berkeley — to bring big-data analytics to the cloud. It defined the 'lakehouse' pattern (combining data warehouses and data lakes) and became the dominant platform for enterprise data engineering and machine learning. In 2024 it released DBRX, an open-weights mixture-of-experts model that beat GPT-3.5-class baselines — a deliberate statement that open models could be trained and served on standard enterprise infrastructure.",
    "Databricks's strategic bet is the AI/BI convergence: rather than selling models, it sells the data platform models are trained and grounded on — retrieval, vector search, feature stores and fine-tuning for the enterprise. Its 2024 acquisition of MosaicML, the open-sourcing of Unity Catalog, and the Mosaic AI platform position it as the anti-closed-lab force in enterprise AI. For the open-weights debate, Databricks is the most powerful corporate argument that the future of AI belongs to the companies that own the data, not the models."
  ], tags: ["enterprise", "data", "open weights"], related: ["hugging-face", "qwen", "fine-tuning", "open-weights-debate"], sources: ["Databricks, 2013 — founding; 2024 — DBRX release"], status: "core" },
  { id: "moonshot-ai", name: "Moonshot AI", category: "companies", year: 2023, tagline: "The Beijing startup behind Kimi — long context as a product thesis.", summary: "Founded 2023 by Yang Zhilin, Moonshot AI built Kimi, one of China's most-used AI assistants, and shocked the world with the open K2 model in 2025.", body: [
    "Moonshot AI was founded in 2023 by Yang Zhilin, a Carnegie Mellon PhD and former Google Brain and Meta AI researcher, with backing from Alibaba, Tencent and HongShan. Its product thesis was long context: the Kimi assistant, launched in 2023, let users paste entire books and documents into a 128k-token window that grew toward millions, making it one of the first mainstream 'chat with your whole file' products and one of China's most popular AI apps.",
    "Moonshot's global moment came in 2025 with Kimi K2: a trillion-parameter open-weights model that matched frontier performance on agentic coding and long-horizon tasks, released under a modified open license. K2's quality made Moonshot a pillar of the Chinese open-model wave alongside DeepSeek, Qwen and Zhipu — and a favorite of Western developers building autonomous coding agents. The company's trajectory — consumer app, then frontier open model — is the template of the new Chinese AI economy."
  ], tags: ["china", "long context", "open weights"], related: ["kimi", "qwen", "zhipu-ai", "deepseek", "context-window", "yang-zhilin"], sources: ["Moonshot AI, 2023 — founding; 2025 — Kimi K2 release"], status: "core" },
  { id: "zhipu-ai", name: "Zhipu AI", category: "companies", year: 2019, tagline: "Tsinghua's AI spin-out — the academic institution that built GLM.", summary: "Founded 2019 from Tsinghua University's KEG lab, Zhipu AI produces the GLM family and ChatGLM, one of China's Big Four AI model makers.", body: [
    "Zhipu AI (智谱) was founded in 2019 as a commercialization of Tsinghua University's Knowledge Engineering Group, one of China's oldest AI research labs. Its GLM (General Language Model) line — from the 2021 pre-training experiments to GLM-4 (2024) and GLM-4.5 (2025) — built an unusually direct bridge between published research and frontier-adjacent open models, and its ChatGLM assistant became one of China's most widely used AI products. Backed by major Chinese tech investors, Zhipu is considered one of the 'Big Four' Chinese AI model companies alongside Moonshot, Baichuan and MiniMax.",
    "Zhipu matters for what it represents: a national champion with roots in public academic research, demonstrating that China's AI ecosystem runs as much on university pipelines as on Big Tech. Its GLM releases — bilingual, open-weights, and increasingly competitive on coding and agents — join DeepSeek, Qwen and Kimi in proving the open-model frontier is a multi-country affair, even as export controls and geopolitical scrutiny reshape how Chinese AI is distributed globally."
  ], tags: ["china", "open weights", "academic"], related: ["glm", "moonshot-ai", "kimi", "qwen", "transformer"], sources: ["Zhipu AI, 2019 — founding; 2024 — GLM-4 release"], status: "core" },
  { id: "bytedance", name: "ByteDance", category: "companies", year: 2012, tagline: "The app factory whose AI assistant Doubao reached hundreds of millions of users.", summary: "ByteDance — maker of TikTok and Douyin — became a frontier AI contender with Doubao, the Seed model family and the world's largest consumer AI distribution.", body: [
    "ByteDance, founded in 2012 by Zhang Yiming, is the Chinese company behind TikTok and Douyin and the world's most valuable startup-turned-corporation. Its AI strategy is distribution at unprecedented scale: the Doubao assistant, launched in 2023, used aggressive free-tier pricing and deep integration across ByteDance's apps to become one of the fastest-growing AI products ever, reaching hundreds of millions of users. Behind it sits the Seed research team, which built frontier-class models — Seed 1.5, Seed 2.0 and the video model Seedance — trained on ByteDance's enormous compute fleet.",
    "ByteDance's significance is the convergence thesis: it pairs a top-tier research lab with a consumer reach no other AI company can match, and it uses the recommendation-engine lineage (the algorithms that made TikTok) to tune AI experiences for engagement. Its AI moves are closely watched both as a product benchmark — Doubao's feature cadence — and as evidence that the next AI battle will be won by whoever controls distribution as much as models."
  ], tags: ["china", "consumer", "distribution"], related: ["recommendation-systems", "generative-ai", "kimi", "qwen"], sources: ["ByteDance, 2023–2025 — Doubao and Seed releases"], status: "core" },
  { id: "safe-superintelligence", name: "Safe Superintelligence (SSI)", category: "companies", year: 2024, tagline: "Ilya Sutskever's lab for alignment-first superintelligence.", summary: "Safe Superintelligence (2024): the Ilya Sutskever–Daniel Gross–Daniel Levy lab with a single product — superintelligence developed safely — valued at $6B within a year of founding.", body: [
    "Safe Superintelligence was founded in June 2024 by Ilya Sutskever, Daniel Gross and Daniel Levy, weeks after Sutskever's departure from OpenAI, with an unusually stark mission: build superintelligence, and make safety the product rather than a post-hoc patch. The lab's structure is deliberately unconventional — research scientists report to a technical CEO, and there are no safety 'teams' separate from the research — and its early hires drew heavily from OpenAI and DeepMind. It raised roughly $1B in late 2024 and was valued at $6B in 2025, one of the largest rounds in AI history for a lab with no product.",
    "SSI's significance is ideological: it is the purest bet that alignment and capability can be built together, and its existence reframes the industry's central tension — a lab racing to the frontier while insisting the safety question is inseparable from the engineering. Its output remains mostly unpublished, its timeline undisclosed, and its valuation a referendum on how much investors believe in alignment-first AGI. Whatever it ships, SSI is the clearest institutional answer to 'what should the people most worried about AI actually do?'"
  ], tags: ["frontier lab", "safety", "us"], related: ["ilya-sutskever", "openai", "ai-safety", "agi", "existential-risk"], sources: ["SSI, 2024 — founding announcement; 2025 — funding round"], status: "emerging" },
  { id: "thinking-machines-lab", name: "Thinking Machines Lab", category: "companies", year: 2025, tagline: "Mira Murati's startup for capable, adaptable, trustworthy AI.", summary: "Thinking Machines Lab (2025): Mira Murati's lab of ex-OpenAI engineers — built around multimodality, verifiable systems and the engineering discipline that shipped ChatGPT at planetary scale.", body: [
    "Thinking Machines Lab was founded in early 2025 by Mira Murati with a core of former OpenAI researchers and engineers — including Barret Zoph and Jonathan Lachman — carrying the thesis that the next frontier is not bigger models but more capable, adaptable and trustworthy systems. Its public framing emphasizes multimodal understanding, verifiable and grounded AI, and the engineering craft of deploying models reliably in the real world — the discipline Murati oversaw as OpenAI's CTO through ChatGPT, GPT-4 and GPT-4o.",
    "The lab raised one of the largest startup rounds of the era in 2025, reportedly valued near $30B by 2026, making it the highest-valued of the OpenAI-alumni ventures. Its significance is the engineer's answer to the lab wars: rather than racing for benchmark tops, Thinking Machines bets that the moat is systems — evaluation, reliability, adaptability — and its trajectory is read as a referendum on whether OpenAI's success was the models or the machine around them."
  ], tags: ["frontier lab", "us", "startup"], related: ["mira-murati", "openai", "multimodal-ai", "ai-safety"], sources: ["Thinking Machines Lab, 2025 — founding announcement"], status: "emerging" },
  { id: "anysphere", name: "Anysphere", category: "companies", year: 2022, tagline: "The startup behind Cursor — the highest-valued AI developer-tool company.", summary: "Anysphere (2022): makers of Cursor, the AI-first code editor whose agentic modes made it the fastest-growing developer product of the era and a multi-billion-dollar company.", body: [
    "Anysphere was founded in 2022 by MIT students Michael Truell, Sualeh Asif, Arvid Lunnemark and Aman Sanger with a simple thesis: the code editor is where AI should live. Cursor, launched in 2023 as a VS Code fork with AI woven into every surface, became the defining developer product of the boom — tab-completion, codebase-aware chat, and agentic modes that edit files, run tests and fix their own mistakes. By 2025 the company was valued in the tens of billions, one of the largest private valuations in software history for a company its age.",
    "Anysphere's significance is that it won the 'AI developer experience' war: it forced every incumbent — GitHub Copilot, JetBrains, Windsurf — into an AI-first redesign, and its Cursor 2.0 agent model became the reference for what an autonomous coding product should be. The company also embodies the era's economics: a tiny team, an enormous valuation, and a product whose growth came from developers who felt the productivity gains themselves. Its main dependencies — frontier model APIs from OpenAI and Anthropic — are both its engine and its risk."
  ], tags: ["startup", "coding", "developer tools"], related: ["cursor", "github-copilot", "ai-coding-assistants", "cognition-ai", "agents"], sources: ["Anysphere, 2022 — founding; 2025 — valuation reports"], status: "core" },
  { id: "cognition-ai", name: "Cognition AI", category: "companies", year: 2023, tagline: "The makers of Devin — the AI software engineer.", summary: "Cognition AI (2023): the startup behind Devin, the first 'AI software engineer', valued at $2B within months — the boldest bet that agents will do the work of junior engineers end-to-end.", body: [
    "Cognition AI was founded in November 2023 by Scott Wu, Steven Hao and Walden Yan, engineers from Cursor and Scale AI, and introduced itself with Devin in March 2024: an 'AI software engineer' that could take a GitHub issue, plan a fix, write the code, run tests and open a pull request. The demo went viral, SWE-bench scores jumped, and investors — a16z and Founders Fund led — valued the company at $2B within months of launch. Devin 2.0 (2025) added worklog and plan modes that made its autonomy legible to human teams.",
    "Cognition's significance is the strongest articulation of the agent-as-colleague thesis: where Copilot and Cursor augment the developer, Cognition aims to replace swaths of the software-engineering workflow itself, and its 'Devin, not copilots' positioning divides the industry between augmentation and automation. Its success — and that of Anysphere — made 'AI-native software company' a recognized category, and its failure modes (hallucinated fixes, unbounded autonomy) became the canonical cautionary tales of the agent era."
  ], tags: ["startup", "agents", "coding"], related: ["ai-coding-assistants", "agents", "anysphere", "github-copilot"], sources: ["Cognition, 2024 — Devin announcement"], status: "core" },
  { id: "character-ai", name: "Character.AI", category: "companies", year: 2021, tagline: "The persona-chat platform Noam Shazeer built — and Google reabsorbed.", summary: "Character.AI (2021): Shazeer and De Freitas's platform of AI personas that became an engagement juggernaut — its technology and founder returning to Google DeepMind in 2024.", body: [
    "Character.AI was founded in November 2021 by Noam Shazeer and Daniel De Freitas, the Google engineers behind LaMDA, to let anyone create and converse with AI personas — historical figures, celebrities, fictional characters, therapist bots. Launched in September 2022, it grew into one of the most-used AI products in the world by engagement, with tens of millions of users and session lengths that dwarfed every other consumer AI app. Its revenue problem — heavy inference costs against stubbornly free users — became the founding cautionary tale of consumer AI economics.",
    "Character.AI's 2024 agreement with Google — licensing the technology and returning Shazeer and roughly a fifth of the staff to DeepMind, where the technology fed Gemini 2.0 — made it the highest-profile example of the talent-and-tech recirculation that now defines the industry. Its significance is double: it proved the enormous demand for AI companionship (and the ethical questions it raises), and its trajectory became the template for how frontier talent cycles between labs and startups."
  ], tags: ["consumer", "chatbots", "google"], related: ["noam-shazeer", "google", "gemini", "chatgpt", "anthropic"], sources: ["Character.AI, 2021 — founding; 2024 — Google agreement"], status: "core" }
];
